def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []

    moves = {
        2: (0, -4),
        3: (3, 0),
        6: (-6, 0),
    }

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue

            if color == 1:
                # The 1 path goes two cells right, then one cell up.
                path = [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]
                endpoint = path[-1]
            elif color in moves:
                dr, dc = moves[color]
                endpoint = (r + dr, c + dc)
                steps = max(abs(dr), abs(dc))
                path = [(r + dr * i // steps, c + dc * i // steps)
                        for i in range(steps + 1)]

            # Draw the connecting 5s and matching endpoint.
            for rr, cc in path[1:-1]:
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 5
            er, ec = endpoint
            if 0 <= er < h and 0 <= ec < w:
                out[er][ec] = color
            paths.append(set((rr, cc) for rr, cc in path
                             if 0 <= rr < h and 0 <= cc < w))

    # Intersections of distinct paths become 4 and send a diagonal down-left.
    intersections = set()
    for i in range(len(paths)):
        for j in range(i + 1, len(paths)):
            intersections.update(paths[i] & paths[j])

    for r, c in intersections:
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1

    return out
